def _verify_chunk_integrity(chunks, cval):
    if len(chunks)!=4:return False
    try:
        cval_raw=_rd(cval)
        for i in range(4):
            check=hashlib.sha3_512(chunks[i]).digest()
            if not _do(check,cval_raw[i*64:(i+1)*64]):return False
        return True
    except:return False

